def Rlnm(l, n, m, k, z, N_t):
    """Function to calculate the translation coefficient (R|R)lmn.
    Input
    l : int
        The principal quantum number for the expansion.
    n : int
        The principal quantum number for the reexpansion.
    m : int
        The magnetic quantum number for the reexpansion.
    k : float
        Wavevector of the optical beam.
    z : float
        The translation distance along z direction
    N_t : int
        Truncated space size.
    Output
    (R|R)lmn : complex
        The translation coefficient (R|R)lmn.
    """
    cache = {}

    def a_coefficient(n_idx, m_idx):
        """Calculate coefficient a_n^m"""
        if n_idx < abs(m_idx):
            return 0.0
        m_abs = abs(m_idx)
        numerator = (n_idx + 1 + m_abs) * (n_idx + 1 - m_abs)
        denominator = (2 * n_idx + 1) * (2 * n_idx + 3)
        return np.sqrt(numerator / denominator)

    def b_coefficient(n_idx, m_idx):
        """Calculate coefficient b_n^m"""
        if n_idx < abs(m_idx):
            return 0.0
        if m_idx >= 0:
            if n_idx < m_idx:
                return 0.0
            numerator = (n_idx - m_idx - 1) * (n_idx - m_idx)
            denominator = (2 * n_idx - 1) * (2 * n_idx + 1)
            if numerator < 0:
                return 0.0
            return np.sqrt(numerator / denominator)
        else:
            if n_idx < -m_idx:
                return 0.0
            numerator = (n_idx - m_idx - 1) * (n_idx - m_idx)
            denominator = (2 * n_idx - 1) * (2 * n_idx + 1)
            if numerator < 0:
                return 0.0
            return -np.sqrt(numerator / denominator)

    def spherical_bessel_j(order, x):
        """Calculate spherical Bessel function of first kind j_n(x)"""
        return scipy.special.spherical_jn(order, x)

    def get_R(l_idx, n_idx, m_idx):
        """Recursively calculate (R|R)_{l,n_idx}^{m_idx}(r_0) with caching"""
        key = (l_idx, n_idx, m_idx)
        if key in cache:
            return cache[key]
        if n_idx < abs(m_idx) or l_idx < 0 or n_idx < 0:
            cache[key] = 0.0
            return 0.0
        if m_idx == 0:
            if n_idx == 0:
                result = (-1) ** l_idx * np.sqrt(2 * l_idx + 1) * spherical_bessel_j(l_idx, k * z)
                cache[key] = result
                return result
            else:
                a_n_m = a_coefficient(n_idx, m_idx)
                a_n_minus1_m = a_coefficient(n_idx - 1, m_idx)
                a_l_m = a_coefficient(l_idx, m_idx)
                a_l_minus1_m = a_coefficient(l_idx - 1, m_idx)
                right_side = a_l_m * get_R(l_idx + 1, n_idx, m_idx) - a_l_minus1_m * get_R(l_idx - 1, n_idx, m_idx)
                if a_n_m != 0:
                    left_side = a_n_minus1_m * get_R(l_idx, n_idx - 1, m_idx)
                    result = (left_side - right_side) / a_n_m
                else:
                    result = 0.0
                cache[key] = result
                return result
        if m_idx > 0:
            b_m_neg_m = b_coefficient(m_idx, -m_idx)
            if b_m_neg_m != 0:
                b_l_neg_m_plus1 = b_coefficient(l_idx, -(m_idx - 1))
                b_l_plus1_neg_m_plus1 = b_coefficient(l_idx + 1, -(m_idx - 1))
